def _buying_price_from_prices(prices):
    """O1: the primary supplier's cost, else the cheapest (None if no prices)."""
    primary = next((p for p in prices if p.primary), None)
    if primary is not None:
        return primary.cost_price
    if prices:
        return min(p.cost_price for p in prices)
    return None


